for year in [2002, 2003]:
    for q in ['03', '06', '09', '12']:
        filepath = f'/app/corpus/treasury_bulletin_{year}_{q}.txt'
        try:
            with open(filepath, 'r', errors='ignore') as f:
                content = f.read()

            if len(content) == 0:
                continue

            # Look for any corporate bond yield data
            # Different search patterns
            patterns = [
                r'corporate.*\d+\.\d+',
                r'Aa.*\d+\.\d+',
                r'yield.*\d+\.\d+',
            ]

            for pattern in patterns:
                matches = re.findall(pattern, content, re.IGNECASE)
                if matches:
                    # Filter to likely yield values (between 4 and 12)
                    filtered = [m for m in matches if any(str(n) in m for n in range(4, 13))]
                    if filtered:
                        print(f"{year}_{q}: Found {len(filtered)} potential yield matches")
                        print(f"  Sample: {filtered[:3]}")
                        break
        except Exception as e:
            pass
