# Let me do one final check - look at ALL yield data in ALL available bulletins
# to see what years actually have monthly data

import os

all_yields = {}

for year in range(1999, 2004):
    for q in ['03', '06', '09', '12']:
        filepath = f'/app/corpus/treasury_bulletin_{year}_{q}.txt'
        if os.path.exists(filepath) and os.path.getsize(filepath) > 0:
            with open(filepath, 'r', errors='ignore') as f:
                content = f.read()

            # Find all years in yield table
            import re
            years = re.findall(r'\|\s*(\d{4})\s*\|\s*nan\s*\|', content)

            if years:
                all_yields[f"{year}_{q}"] = list(set(years))

print("Years with yield data in each bulletin:")
for k, v in sorted(all_yields.items()):
    print(f"  {k}: {v}")
